import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';

function Cart({ cart, removeFromCart, user, setCart }) {
  const [isProcessing, setIsProcessing] = useState(false);
  const navigate = useNavigate();
  const total = cart.reduce((sum, item) => sum + parseFloat(item.price), 0);

  const handleCheckout = async () => {
    if (!user) {
        alert("Please login to checkout");
        navigate('/login');
        return;
    }
    setIsProcessing(true);
    try {
      await axios.post('http://localhost:5000/api/checkout', {
        user_id: user.id,
        total_amount: total
      });
      alert("Payment successful! Order placed.");
      setCart([]);
      navigate('/profile');
    } catch (error) {
      alert("Checkout failed");
    }
    setIsProcessing(false);
  };

  if (cart.length === 0) return <h2 className="text-2xl text-center mt-10">Your cart is empty.</h2>;

  return (
    <div className="max-w-2xl mx-auto bg-white p-8 rounded-lg shadow-md">
      <h2 className="text-3xl font-bold mb-6 border-b pb-4">Shopping Cart</h2>
      {cart.map((item, index) => (
        <div key={index} className="flex justify-between items-center mb-4 pb-4 border-b">
          <div>
            <h4 className="text-lg font-bold">{item.name}</h4>
            <p className="text-gray-600">${item.price}</p>
          </div>
          <button onClick={() => removeFromCart(item.id)} className="text-red-500 hover:text-red-700 font-bold">
            Remove
          </button>
        </div>
      ))}
      <div className="text-right mt-6">
        <h3 className="text-2xl font-bold">Total: ${total.toFixed(2)}</h3>
        <button 
          onClick={handleCheckout} 
          disabled={isProcessing}
          className="mt-4 bg-green-500 text-white px-8 py-3 rounded-lg text-lg hover:bg-green-600 transition"
        >
          {isProcessing ? "Processing Payment..." : "Pay & Checkout"}
        </button>
      </div>
    </div>
  );
}
export default Cart;
